-- Validate provider inputs once, at the authoritative write boundary. Category
-- bounds count UTF-16 code units, matching the existing JavaScript CMP adapter.
CREATE OR REPLACE FUNCTION public.get_unit_website_consent_bindings(p_unit bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_manage_unit_configuration(p_unit) THEN RAISE insufficient_privilege; END IF;
 RETURN public.unit_measurement_consent_scope_internal(p_unit)||jsonb_build_object(
  'saved_origins',(SELECT coalesce(data->'measurement_websites','[]'::jsonb) FROM public.units WHERE id=p_unit),'bindings',
  coalesce((SELECT jsonb_agg(jsonb_build_object('id',b.id,'websiteOrigin',b.website_origin,'platform',b.platform,
   'providerConfig',b.provider_config,'version',b.version,'confirmedRevision',b.confirmed_revision,
   'state',CASE WHEN NOT b.enabled THEN CASE WHEN b.confirmed_revision IS NULL THEN 'draft' ELSE 'disabled' END
     WHEN b.confirmed_revision IS DISTINCT FROM public.unit_measurement_consent_scope_internal(p_unit)->>'consentRevision' THEN 'confirmation_required'
     WHEN public.website_consent_binding_effective_internal(b) THEN 'ready' ELSE 'unavailable' END)
    ORDER BY b.website_origin) FROM analytics.website_consent_bindings b WHERE b.unit=p_unit),'[]'::jsonb));
END $$;
REVOKE ALL ON FUNCTION public.get_unit_website_consent_bindings(bigint) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.get_unit_website_consent_bindings(bigint) TO authenticated;

-- A Unit lock serializes authoring with the canonical Unit aggregate save.
-- Version zero means absent. Every write advances the version, including off.
CREATE OR REPLACE FUNCTION public.form_measurement_runtime_supported_internal(
 p_profile text,p_origin text,p_parents text[])
RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public,extensions AS $$
 SELECT coalesce(p_profile='gtm-v1'
  AND p_origin ~ '^https://[a-z0-9][a-z0-9-]{0,61}[a-z0-9]\.pages\.dev$'
  AND cardinality(p_parents) BETWEEN 1 AND 32,false);
$$;
REVOKE ALL ON FUNCTION public.form_measurement_runtime_supported_internal(text,text,text[])
 FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.unit_measurement_parent_origins_internal(p_unit bigint)
RETURNS text[] LANGUAGE sql STABLE SET search_path=public,extensions AS $$
 WITH scope AS (
  SELECT r.parent_origins,CASE WHEN jsonb_typeof(u.data->'measurement_websites')='array'
   THEN CASE WHEN jsonb_array_length(u.data->'measurement_websites')<=10
    THEN u.data->'measurement_websites' ELSE '[]'::jsonb END ELSE '[]'::jsonb END websites
  FROM public.units u JOIN analytics.unit_runtime r ON r.unit=u.id WHERE u.id=p_unit
 ), allowed AS (
  SELECT origin,min(priority) priority FROM scope CROSS JOIN LATERAL (
   SELECT value origin,ordinality priority FROM unnest(parent_origins) WITH ORDINALITY AS baseline(value,ordinality)
   UNION ALL
   SELECT value,2147483647 FROM jsonb_array_elements_text(websites) AS saved(value)
    WHERE length(value)<=2048 AND value ~ (public.configuration_settings_contract_internal_v1()#>>'{unit,measurement_websites,items,allOf,0,pattern}')
  ) origins GROUP BY origin
 ) SELECT coalesce(array_agg(origin ORDER BY priority,origin),'{}'::text[]) FROM allowed;
$$;
REVOKE ALL ON FUNCTION public.unit_measurement_parent_origins_internal(bigint) FROM PUBLIC,anon,authenticated,service_role;

-- One semantic notice owner for admin exports and public form policy.
CREATE OR REPLACE FUNCTION public.form_measurement_runtime_internal(p_form bigint)
RETURNS jsonb LANGUAGE sql STABLE SET search_path=public,extensions AS $$
 WITH status AS MATERIALIZED (
  SELECT public.form_measurement_status_internal(p_form) AS s
 )
 SELECT jsonb_build_object('enabled',s->'requested_enabled','organization_allowed',s->'organization_allowed',
  'runtime_supported',s->'runtime_supported','eligible',s->'eligible','organization',o.organization,'unit',u.id,
  'runtime_origin',CASE WHEN s->'eligible'='true'::jsonb THEN r.runtime_origin END,
  'measurement_consent_bridge',coalesce(u.data->'measurement_consent_bridge'='true'::jsonb,false),
  'privacy_url',CASE WHEN notice.available THEN u.data->>'measurement_privacy_url' END,
  'consent_notice',CASE WHEN notice.available THEN jsonb_build_object('layout',coalesce(u.data->>'measurement_consent_layout','bar'),
   'title',nullif(btrim(u.data->>'measurement_consent_title'),''),'text',nullif(btrim(u.data->>'measurement_consent_text'),'')) END,
  'approved_hosts',CASE WHEN s->'eligible'='true'::jsonb THEN to_jsonb(public.unit_measurement_parent_origins_internal(u.id)) ELSE '[]'::jsonb END,
  -- Semantic notice scope is independent of runtime deployment and effective hosts.
  -- Changes behind an unchanged GTM ID/privacy URL require a consent-version increment.
  'consent_revision',public.unit_measurement_consent_scope_internal(u.id)->>'consentRevision',
  'website_consent_bindings',public.website_consent_bindings_policy_internal(u.id),
  'measurement_protocol',3,'form_link',f.link,'profile',r.runtime_profile,'required_purposes',jsonb_build_array('analytics','marketing'),
  'enhanced_conversions_unavailable',false,
  -- Append the opt-in only when enabled to preserve existing saved choices.
  'processing_revision',md5((jsonb_build_array(3,o.organization,u.id,u.data->'measurement_gtm_container',u.data->'measurement_scripts',
   u.data->'measurement_privacy_url',coalesce(u.data->'measurement_consent_version','1'::jsonb),r.runtime_profile,r.runtime_origin,
   public.unit_measurement_parent_origins_internal(u.id),r.collector_origins,r.revision,s->'policy_revision',u.data->'measurement_enabled',
   org.data->'FORM_MEASUREMENT_ENABLED',s->'requested_enabled')
   ||CASE WHEN u.data->'measurement_consent_bridge'='true'::jsonb THEN jsonb_build_array(true) ELSE '[]'::jsonb END
   ||CASE WHEN nullif(u.data->>'measurement_consent_title','') IS NOT NULL OR nullif(u.data->>'measurement_consent_text','') IS NOT NULL
     THEN jsonb_build_array(u.data->'measurement_consent_title',u.data->'measurement_consent_text') ELSE '[]'::jsonb END
   ||CASE WHEN public.website_consent_bindings_policy_internal(u.id) <> '[]'::jsonb
     THEN jsonb_build_array(public.website_consent_bindings_policy_internal(u.id)) ELSE '[]'::jsonb END)::text),
  'configuration_revision',md5(jsonb_build_array(u.data->'measurement_gtm_container',u.data->'measurement_scripts',
   u.data->'measurement_enabled',org.data->'FORM_MEASUREMENT_ENABLED',s->'requested_enabled')::text),
  'runtime_revision',coalesce(r.revision,0),'policy_revision',s->'policy_revision','valid_for_seconds',60,'consent_required',true)
 FROM public.forms f JOIN public.occasions o ON o.id=f.occasion
 JOIN public.units u ON u.id=o.unit AND u.organization=o.organization
 JOIN public.organizations org ON org.id=o.organization
 LEFT JOIN analytics.organization_policy p ON p.organization=o.organization
  LEFT JOIN analytics.unit_runtime r ON r.unit=u.id
 CROSS JOIN status
 -- A configured notice is useful without tags only for an effective transfer.
 -- Otherwise disabled measurement must not create an unsolicited cookie banner.
 CROSS JOIN LATERAL (SELECT s->'eligible'='true'::jsonb OR
  public.website_consent_bindings_policy_internal(u.id) @> '[{"effective":true}]'::jsonb AS available) notice
 WHERE f.id=p_form;
$$;
REVOKE ALL ON FUNCTION public.form_measurement_runtime_internal(bigint) FROM PUBLIC,anon,authenticated,service_role;

CREATE TABLE IF NOT EXISTS analytics.conversion_facts (
 "order" bigint NOT NULL REFERENCES eshop.orders(id) ON DELETE CASCADE,
 kind text NOT NULL CHECK(kind IN ('purchase','waitlist','free_registration')),
 PRIMARY KEY("order",kind),
 event_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,
 payload jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE analytics.conversion_facts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON analytics.conversion_facts FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.can_read_form_measurement_runtime(p_form bigint,p_organization bigint,p_unit bigint,p_runtime_origin text,p_parent_origin text)
RETURNS boolean LANGUAGE sql STABLE SET search_path=public,extensions AS $$
 SELECT auth.role()='service_role' AND public.can_read_public_form_measurement(p_form) AND
  EXISTS(SELECT 1 FROM public.forms f JOIN public.occasions o ON o.id=f.occasion
   JOIN public.units u ON u.id=o.unit AND u.organization=o.organization
   JOIN analytics.unit_runtime r ON r.unit=u.id
   WHERE f.id=p_form AND o.organization=p_organization AND u.id=p_unit AND r.runtime_origin=p_runtime_origin
   AND p_parent_origin=ANY(public.unit_measurement_parent_origins_internal(u.id))
   AND public.form_measurement_status_internal(f.id)->'eligible'='true'::jsonb);
$$;
REVOKE ALL ON FUNCTION public.can_read_form_measurement_runtime(bigint,bigint,bigint,text,text) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.get_form_measurement_runtime_config(
 p_form_link text,p_organization bigint,p_unit bigint,p_runtime_origin text,p_parent_origin text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE fid bigint:=public.resolve_form_link_internal(p_form_link); result jsonb;
BEGIN
 IF NOT public.can_read_form_measurement_runtime(fid,p_organization,p_unit,p_runtime_origin,p_parent_origin) THEN
  RAISE insufficient_privilege USING MESSAGE='form measurement runtime unavailable';
 END IF;
 SELECT jsonb_build_object('organization',o.organization,'unit',u.id,'form_id',f.id,'form_link',f.link,
  'runtime_origin',r.runtime_origin,'parent_origin',p_parent_origin,'profile',r.runtime_profile,
  'ancestor_origins',public.unit_measurement_parent_origins_internal(u.id),'collector_origins',r.collector_origins,'policy',public.form_measurement_runtime_internal(f.id)-ARRAY['privacy_url','consent_notice','approved_hosts'],
  'gtm_container',u.data->>'measurement_gtm_container','scripts',u.data->>'measurement_scripts') INTO result
 FROM public.forms f JOIN public.occasions o ON o.id=f.occasion
 JOIN public.units u ON u.id=o.unit AND u.organization=o.organization
 JOIN analytics.unit_runtime r ON r.unit=u.id
 WHERE f.id=fid;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.get_form_measurement_runtime_config(text,bigint,bigint,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_form_measurement_runtime_config(text,bigint,bigint,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.unit_measurement_approval_internal(p_unit bigint)
RETURNS jsonb LANGUAGE sql STABLE SET search_path=public,extensions AS $$
 WITH status AS (
  SELECT u.id,u.organization,coalesce(p.enabled,false) allowed,
   public.form_measurement_runtime_supported_internal(r.runtime_profile,r.runtime_origin,r.parent_origins)
    AND NOT public.is_demo_unit(u.id) supported,q.requested_at,
   to_jsonb(public.unit_measurement_parent_origins_internal(u.id)) approved_origins,
   coalesce(u.data->'measurement_websites','[]'::jsonb) saved_origins,
   coalesce(q.requested_origins,'[]'::jsonb) requested_origins,
   EXISTS(SELECT FROM public.email_messages m
    JOIN public.organization_users ou ON ou.organization=u.organization
     AND ou."user"=m.recipient_user AND ou.is_admin
    WHERE m.unit=u.id AND m.organization=u.organization AND m.code='MEASUREMENT_APPROVAL_REQUEST'
     AND coalesce((m.data->>'request_revision')::integer,1)=q.revision
     AND public.get_user_delivery_email(ou."user")=m.recipient
     -- Accepted/ambiguous sends must not be duplicated. Terminal undelivered
     -- generations are retryable; expired queued work cannot prove activity.
     AND (m.workflow_state IN ('accepted','sending','unknown') OR
      (m.workflow_state IN ('pending','retry_wait','preparing','blocked') AND m.expires_at>now()))) active_request
  FROM public.units u
  LEFT JOIN analytics.organization_policy p ON p.organization=u.organization
  LEFT JOIN analytics.unit_runtime r ON r.unit=u.id
  LEFT JOIN analytics.unit_measurement_request q ON q.unit=u.id WHERE u.id=p_unit
 ) SELECT jsonb_build_object('approved',allowed AND supported,'organization_allowed',allowed,
  'runtime_supported',supported,'requested_at',requested_at,'approved_origins',approved_origins,
  'saved_origins',saved_origins,'requested_origins',requested_origins,
  'request_state',CASE WHEN requested_at IS NULL THEN 'not_requested'
    WHEN active_request THEN 'requested' ELSE 'retry_available' END,
  'can_request',NOT public.is_demo_unit(id) AND
   NOT (allowed AND supported) AND NOT active_request) FROM status;
$$;
REVOKE ALL ON FUNCTION public.unit_measurement_approval_internal(bigint) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.email_intent_valid(p_message public.email_messages) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_order eshop.orders; v_pi eshop.payment_info; v_occ public.occasions; v_form public.forms; v_feature jsonb; v_deposit jsonb; v_template_epoch bigint; template_audit jsonb; bank_enabled boolean;
BEGIN
 IF p_message.message_kind='custom' AND p_message.code='MEASUREMENT_APPROVAL_REQUEST' THEN
  RETURN EXISTS(SELECT 1 FROM analytics.unit_measurement_request q JOIN public.units u ON u.id=q.unit
   JOIN public.organization_users ou ON ou.organization=u.organization AND ou."user"=p_message.recipient_user AND ou.is_admin
   WHERE q.unit=p_message.unit AND u.organization=p_message.organization AND NOT public.is_demo_unit(u.id)
    AND q.revision=coalesce((p_message.data->>'request_revision')::integer,1)
    AND public.unit_measurement_approval_internal(u.id)->'approved'='false'::jsonb
    AND public.get_user_delivery_email(ou."user")=p_message.recipient);
 END IF;
 IF p_message.message_kind='admin_notification_digest' THEN
  RETURN p_message.recipient IS NOT DISTINCT FROM public.get_user_delivery_email(p_message.recipient_user)
   AND coalesce(jsonb_array_length(public.notification_center_email_context_internal(p_message.notification_dispatch_id,p_message.recipient_user)->'items'),0)>0;
 END IF;

 PERFORM public.require_service_role();
 IF public.is_demo_occasion(p_message.occasion) THEN RETURN false; END IF;
 IF p_message.expires_at<=now() THEN RETURN false; END IF;
 IF p_message.message_kind='sign_in' AND EXISTS(SELECT 1 FROM public.occasion_users ou
   WHERE ou.occasion=p_message.occasion AND ou."user"=p_message.recipient_user AND (ou.is_editor OR ou.is_editor_view OR ou.is_manager)) THEN
  RETURN false; END IF;
 IF p_message.message_kind='custom' AND p_message.code='TEAM_INVITATION' THEN
  RETURN EXISTS(SELECT 1 FROM public.access_invitations i WHERE i.message_id=p_message.message_id
   AND i.accepted_at IS NULL AND public.access_invitation_valid_internal_v1(i)
   AND i.email=p_message.recipient AND i.occasion IS NOT DISTINCT FROM p_message.occasion AND i.unit=p_message.unit AND i.organization=p_message.organization);
 END IF;
 IF p_message.message_kind='custom' AND p_message.code='TEAM_ACCESS_NOTICE' THEN
  RETURN public.can_manage_member_access_as_actor_internal_v1(p_message.producer_actor,
   CASE WHEN p_message.occasion IS NULL THEN 'unit' ELSE 'occasion' END,coalesce(p_message.occasion,p_message.unit))
   AND public.get_user_delivery_email(p_message.recipient_user)=p_message.recipient
   AND CASE WHEN p_message.occasion IS NULL THEN EXISTS(SELECT 1 FROM public.unit_users WHERE unit=p_message.unit AND "user"=p_message.recipient_user)
    ELSE EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=p_message.occasion AND "user"=p_message.recipient_user) END;
 END IF;
 IF p_message.message_kind='custom' AND p_message.code='UNIT_VERIFICATION_REQUEST' THEN
  RETURN EXISTS(SELECT 1 FROM public.unit_legal_profiles p JOIN public.units u ON u.id=p.unit_id
   JOIN public.organization_users ou ON ou.organization=u.organization AND ou."user"=p_message.recipient_user AND ou.is_admin
   WHERE p.unit_id=p_message.unit AND u.organization=p_message.organization AND p.status='pending'
    AND p.revision=p_message.source_version
    AND public.get_user_delivery_email(ou."user")=p_message.recipient);
 END IF;
 IF p_message.message_kind='custom' AND p_message.code='ORDER_OVERVIEW' THEN RETURN false; END IF;
 IF p_message.message_kind='sale_opening_confirmation' THEN RETURN false; END IF;
 IF p_message.message_kind='sale_opening_opened' THEN
  RETURN public.sale_opening_intent_valid_internal(p_message);
 END IF;
 IF p_message.order_id IS NULL THEN
  IF p_message.recipient_user IS NOT NULL AND p_message.message_kind<>'deletion_complete' THEN
   IF p_message.message_kind<>'gotrue' AND public.get_user_delivery_email(p_message.recipient_user) IS DISTINCT FROM p_message.recipient THEN RETURN false; END IF;
   IF p_message.data ? 'sign_in_code_version' AND NOT EXISTS(SELECT 1 FROM public.sign_in_codes WHERE user_id=p_message.recipient_user AND version::text=p_message.data->>'sign_in_code_version' AND expires_at>now() AND consumed_at IS NULL AND attempts<5) THEN RETURN false; END IF;
   IF p_message.data ? 'password_version' AND NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_message.recipient_user AND encode(extensions.digest(encrypted_password,'sha256'),'hex')=p_message.data->>'password_version') THEN RETURN false; END IF;
   IF p_message.data ? 'reset_hash' AND NOT EXISTS(SELECT 1 FROM public.user_reset_token WHERE "user"=p_message.recipient_user AND encode(extensions.digest(token::text,'sha256'),'hex')=p_message.data->>'reset_hash') THEN RETURN false; END IF;
  END IF;
  IF p_message.data ? 'deletion_request' AND NOT EXISTS(SELECT 1 FROM public.account_deletion_requests WHERE id=(p_message.data->>'deletion_request')::uuid AND status IN ('email_pending','email_sent') AND expires_at>now()) THEN RETURN false; END IF;
  IF p_message.data ? 'google_attempt' AND NOT EXISTS(SELECT 1 FROM public.external_login_attempts WHERE id=(p_message.data->>'google_attempt')::uuid AND mailbox_hash=p_message.data->>'mailbox_hash' AND expires_at>now() AND NOT mailbox_verified) THEN RETURN false; END IF;
  RETURN true;
 END IF;
 SELECT * INTO v_order FROM eshop.orders WHERE id=p_message.order_id;
 IF v_order.id IS NULL OR v_order.occasion<>p_message.occasion THEN RETURN false; END IF;
 IF p_message.data->>'repair_payment_fingerprint' IS NOT NULL AND p_message.data->>'repair_payment_fingerprint' IS DISTINCT FROM public.order_email_payment_fingerprint(v_order.id) THEN RETURN false; END IF;
 IF p_message.message_kind='custom' AND p_message.code='ORDER_OVERVIEW' THEN
  RETURN v_order.data->>'email'=p_message.recipient AND EXISTS(
   SELECT 1 FROM eshop.order_overview_sources s JOIN eshop.waitlist_capabilities c USING(token_hash)
   WHERE s.command_id=(p_message.data->>'order_overview_command')::uuid AND c.kind='order_view'
   AND c.order_id=v_order.id AND c.form_id=v_order.form AND c.organization_id=p_message.organization
   AND c.revoked_at IS NULL AND c.expires_at>now() AND s.expires_at=c.expires_at);
 END IF;
 IF p_message.message_kind='waitlist_confirmation' THEN
  RETURN v_order.state='waitlisted' AND v_order.data->>'email'=p_message.recipient;
 END IF;
 IF p_message.message_kind='waitlist_offer' THEN
  RETURN v_order.state='waitlisted' AND v_order.data->>'email'=p_message.recipient AND EXISTS(
   SELECT 1 FROM eshop.waitlist_offers w JOIN eshop.waitlist_offer_slots s ON s.offer_id=w.id
   WHERE w.id=(p_message.data->>'offer_id')::uuid AND w.order_id=v_order.id AND w.expires_at>clock_timestamp() AND s.outcome='pending');
 END IF;
 IF p_message.message_kind IN ('order_confirmation','order_update','order_reminder','order_payment_notice','order_storno','order_tickets') THEN
  SELECT * INTO v_occ FROM public.occasions WHERE id=v_order.occasion;
  SELECT * INTO v_pi FROM eshop.payment_info WHERE id=v_order.payment_info;
  v_template_epoch:=coalesce((SELECT e.revision FROM eshop.payment_template_epochs e WHERE e.occasion_id=v_order.occasion),0);
  bank_enabled:=coalesce(public.payment_method_policy_enabled_internal(v_occ.unit,'bank'),false);
  IF p_message.data ? 'paymentTemplateEpoch' THEN
   IF (p_message.data->>'paymentTemplateEpoch')::bigint IS DISTINCT FROM v_template_epoch THEN RETURN false; END IF;
  ELSIF p_message.prepared IS NOT NULL AND (NOT bank_enabled OR public.payment_method_is_online_internal(v_pi.payment_method)) THEN
   -- An encrypted legacy snapshot has no attestation for the current template.
   -- Preserve it as audit; a new authorized preparation must replace the intent.
   RETURN false;
  END IF;
  IF NOT bank_enabled OR public.payment_method_is_online_internal(v_pi.payment_method) THEN
   template_audit:=public.payment_template_audit_internal(v_order.occasion);
   IF template_audit->'compatible' IS DISTINCT FROM 'true'::jsonb THEN RETURN false; END IF;
  END IF;
 END IF;
 IF p_message.message_kind IN ('order_confirmation','order_update','order_reminder','order_payment_notice') THEN
  IF p_message.data#>>'{collectionAction,policyRevision}' IS NULL THEN RETURN false; END IF;
  IF public.payment_collection_action_internal(v_order.id)->'policyRevision' IS DISTINCT FROM p_message.data#>'{collectionAction,policyRevision}' THEN RETURN false; END IF;
 END IF;
 IF p_message.data#>'{collectionAction,allowed}'='true'::jsonb THEN
 IF (
  public.payment_collection_action_internal(v_order.id)->'allowed' IS DISTINCT FROM 'true'::jsonb OR
  public.payment_collection_action_internal(v_order.id)->'policyRevision' IS DISTINCT FROM p_message.data#>'{collectionAction,policyRevision}') THEN RETURN false; END IF;
 END IF;
 IF p_message.message_kind='order_storno' THEN RETURN true; END IF;
 IF v_order.state IN ('storno','expired','preparing_payment') THEN RETURN false; END IF;
 IF p_message.message_kind IN ('order_payment_notice','order_tickets') THEN
  IF EXISTS(SELECT 1 FROM eshop.payment_info WHERE id=v_order.payment_info AND public.payment_method_is_online_internal(payment_method))
   AND public.provider_order_payment_projection_internal(v_order.id)->>'admissionState' IS DISTINCT FROM 'valid' THEN RETURN false; END IF;
  RETURN v_order.state IN ('paid','sent') AND v_order.email_payment_version=p_message.source_version
   AND (p_message.data->>'manual'='true' OR v_order.data->>'email'=p_message.recipient);
 END IF;
 IF p_message.message_kind='order_confirmation' THEN
  RETURN public.order_checkout_email_kind_internal(v_order.id)='order_confirmation'
   AND v_order.state IN ('ordered','paid') AND v_order.email_payment_version=p_message.source_version
   AND v_order.data->>'email'=p_message.recipient;
 END IF;
 IF p_message.message_kind='order_reminder' THEN
  IF public.payment_collection_action_internal(v_order.id)->'allowed' IS DISTINCT FROM 'true'::jsonb THEN RETURN false; END IF;
  SELECT * INTO v_pi FROM eshop.payment_info WHERE id=v_order.payment_info;
  IF v_pi.payment_method<>'bank' OR v_pi.data#>>'{payment_policy,mode}'='none' THEN RETURN false; END IF;
  SELECT * INTO v_occ FROM public.occasions WHERE id=v_order.occasion;
  SELECT * INTO v_form FROM public.forms WHERE id=v_order.form;
  SELECT x INTO v_feature FROM jsonb_array_elements(v_occ.features) x WHERE x->>'code'='form';
  SELECT x INTO v_deposit FROM jsonb_array_elements(v_occ.features) x WHERE x->>'code'='deposit';
  IF p_message.target_time<now()-interval '7 days' OR p_message.source_version IS DISTINCT FROM v_pi.email_reminder_version
   OR coalesce((v_feature->>'is_enabled')::boolean,false)=false
   OR coalesce((v_form.data->>'is_reminder_enabled')::boolean,(v_feature->>'reminder_is_enabled')::boolean,true)=false THEN RETURN false; END IF;
  IF (p_message.data->>'is_deposit_reminder')::boolean IS TRUE THEN
   RETURN v_order.state IN ('paid','sent') AND v_pi.deposit_amount IS NOT NULL AND coalesce(v_pi.paid,0)-coalesce(v_pi.returned,0)<v_pi.amount
    AND (v_deposit->>'is_enabled')::boolean IS TRUE AND v_deposit->>'deposit_deadline' IS DISTINCT FROM 'on_site';
  END IF;
  RETURN v_order.state='ordered' AND v_pi.deadline IS NOT NULL AND coalesce((v_pi.data->>'current_version_reminded')::boolean,false)=false;
 END IF;
 RETURN true;
END $$;
NOTIFY pgrst, 'reload schema';
COMMIT;
